// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a pool with a non-zero baseToken (e.g., address(this) itself as a mock ERC20)
        address baseToken = address(this);  // not address(0)
        address nft = address(0x1234);
        uint128 virtualBase = 1000 ether;
        uint128 virtualNft = 100;
        uint56 changeFee = 1;
        uint16 feeRate = 100; // 1%
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        // Call initialize directly (since the test contract is the factory) – the onlyOwner modifier is bypassed in test
        // But onlyOwner checks Factory(factory).ownerOf(uint160(address(this))) – we cheat by setting owner via hack
        // In Foundry, we can just call initialize directly because the access control passes: address(this) is the factory,
        // and the pool's ownerOf will be looked up in the Factory, but Factory is the test contract itself.
        // To make it simple, we use vm.startPrank and deploy a mock Factory? No – the test contract IS the factory per setUp.
        // So we can call initialize directly.
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties);

        // Now test availableForFlashLoan on a tokenId not owned by the pool
        uint256 tokenId = 1;
        // The pool does not own tokenId 1, so availableForFlashLoan should return false
        bool result = c.availableForFlashLoan(nft, tokenId);

        // REFERENCE behavior: baseToken is set correctly (address(this)), returns false because pool doesn't own token
        // BUGGY behavior: baseToken is overwritten to address(0), but the return value depends only on ownership, which remains false.
        // Actually the divergence is in baseToken state, not in return value. But the test must assert something that *differs*.
        // The specification says: after availableForFlashLoan completes, baseToken differs between P and M.
        // So we can assert c.baseToken() != address(0) for reference, but the bug sets it to address(0).
        // Thus we assert that c.baseToken() == baseToken (the original value).
        assertTrue(c.baseToken() == baseToken, "baseToken should be the input value, not address(0)");
    }
}

