        // Call availableForFlashLoan on uninitialized pool with a non-existent token
        bool ok = true;
        try c.availableForFlashLoan(address(0x1234), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // Now check that initialized() remains false (i.e., the reference returned false, not reverted)
