import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // availableForFlashLoan does not change state; after it, payRoyalties remains its initial value (false)
        // But the bug toggles it in setPayRoyalties, which was never called.
        // So we just read payRoyalties after a dummy call.
        // First we need the pool to own a token for availableForFlashLoan to inspect.
        // We mint a token to the pool to make the call pass the try/catch.
        // Using mint is not allowed – instead we exploit the fact that the constructor sets
        // the factory to address(this), so we can call create to mint a token? No – too heavy.
        // Simpler: call availableForFlashLoan on a token that reverts (zero address) – then it returns false.
        // The bug doesn't affect this function, so the state after is the same as before: payRoyalties = false.
        c.availableForFlashLoan(address(0), 0);
        // Reference: payRoyalties() returns false; bug: also false because setPayRoyalties not called.
        // Wait – the bug is in setPayRoyalties, but we never call it. So the divergence does NOT appear.
        // We need to call setPayRoyalties first.
        // The bug: setPayRoyalties toggles the value. So calling setPayRoyalties(true) sets payRoyalties to false (reference) vs true (bug).
        // But we are only the owner if we hold the NFT. The factory is address(this), so ownerOf(uint160(address(c))) is address(this).
        // So we are the owner.
        // Call setPayRoyalties(true).
        c.setPayRoyalties(true);
        // Now payRoyalties() should be true in reference, false in bug.
        bool actual = c.payRoyalties();
        assertTrue(actual);
    }
}

