pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Set up: the factory needs to be this test contract, and the pool must be "owned" by this test.
        // The onlyOwner check in setUseStolenNftOracle uses `Factory(factory).ownerOf(uint160(address(this)))`.
        // We need to mock that by having the factory return this test as owner. Since we deployed C with factory=address(this),
        // we must ensure that when C calls Factory(address(this)).ownerOf(uint160(address(this))), it returns a non-zero address.
        // The simplest way: deploy a minimal Factory-like contract that returns this test address.
        // But the problem says "Interact ONLY through c" and no extra contracts.
        // The C constructor takes _factory, _royaltyRegistry, _stolenNftOracle. We pass address(this) for all.
        // However, in the onlyOwner modifier: `if (msg.sender != Factory(factory).ownerOf(uint160(address(this))))`.
        // Factory(factory).ownerOf(uint160(address(this))) will call the function `ownerOf` on address(this) (the test contract).
        // The test contract does not have an `ownerOf` function; the call will revert, so `setUseStolenNftOracle` will always revert.
        // To make the test work, we need the factory to actually return this test as owner.
        // Since we cannot deploy extra contracts, we must use a different approach: the onlyOwner check uses `Factory(factory).ownerOf(uint160(address(this)))`.
        // If `factory` is set to a contract that implements `ownerOf` returning the correct owner, we need that contract.
